source='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Connect the outermost non-background cells on each row and column.
    for r in range(h):
        cols = [c for c, value in enumerate(grid[r]) if value != background]
        if len(cols) >= 2:
            for c in range(cols[0], cols[-1] + 1):
                if grid[r][c] == background:
                    out[r][c] = 3

    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] != background]
        if len(rows) >= 2:
            for r in range(rows[0], rows[-1] + 1):
                if grid[r][c] == background:
                    out[r][c] = 3

    return out
'''
